package com.nephh.business;
import com.nephh.common.ApiResponse;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.http.*;
import org.springframework.core.io.FileSystemResource;
import org.springframework.beans.factory.annotation.Value;
import java.nio.file.*;
import java.util.*;
import static com.nephh.business.AccessService.*;

@RestController @RequestMapping("/api/business")
public class SupportController {
 private final JdbcTemplate db;private final AccessService access;private final OrderController orders;private final Path files;
 public SupportController(JdbcTemplate db,AccessService access,OrderController orders,@Value("${app.upload-directory:.data/uploads}")String directory){this.db=db;this.access=access;this.orders=orders;this.files=Path.of(directory).toAbsolutePath().normalize();}
 @PostMapping("/orders/{id}/attachments") public ApiResponse<?> upload(@AuthenticationPrincipal Jwt jwt,@PathVariable long id,@RequestParam MultipartFile file)throws Exception{var a=access.actor(jwt);var order=orders.readable(a,id);if((!Objects.equals(order.get("assignee_id"),a.id())&&db.queryForObject("select count(*) from order_participant where order_id=? and user_id=?",Integer.class,id,a.id())==0)||!Set.of("ACCEPTED","PROCESSING").contains(order.get("status")))deny();if(file.isEmpty()||file.getSize()>5*1024*1024)bad("图片大小应在1字节至5MB之间");String type=file.getContentType();if(type==null||!Set.of("image/jpeg","image/png","image/webp").contains(type))bad("仅支持JPEG、PNG、WebP图片");byte[] bytes=file.getBytes();boolean valid=type.equals("image/jpeg")?bytes.length>3&&(bytes[0]&255)==255&&(bytes[1]&255)==216:type.equals("image/png")?bytes.length>8&&(bytes[0]&255)==137&&bytes[1]==80&&bytes[2]==78&&bytes[3]==71:bytes.length>12&&new String(bytes,0,4,java.nio.charset.StandardCharsets.US_ASCII).equals("RIFF")&&new String(bytes,8,4,java.nio.charset.StandardCharsets.US_ASCII).equals("WEBP");if(!valid)bad("图片内容与类型不符");String name=UUID.randomUUID().toString();String original=Objects.toString(file.getOriginalFilename(),"图片").replaceAll("[\\r\\n]","");if(original.length()>200)original=original.substring(original.length()-200);Files.createDirectories(files);Files.write(files.resolve(name),bytes);try{db.update("insert into attachment(order_id,uploader_id,original_name,storage_name,content_type) values(?,?,?,?,?)",id,a.id(),original,name,type);}catch(Exception e){Files.deleteIfExists(files.resolve(name));throw e;}access.audit(a,"UPLOAD","ORDER",id,null,original);return ApiResponse.ok(null);}
 @GetMapping("/attachments/{id}") public ResponseEntity<?> download(@AuthenticationPrincipal Jwt jwt,@PathVariable long id){var a=access.actor(jwt);var row=access.one("select * from attachment where id=?",id);orders.readable(a,((Number)row.get("order_id")).longValue());Path path=files.resolve(row.get("storage_name").toString()).normalize();if(!path.startsWith(files)||!Files.isRegularFile(path))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND,"附件不存在");return ResponseEntity.ok().header("X-Content-Type-Options","nosniff").contentType(MediaType.parseMediaType(row.get("content_type").toString())).body(new FileSystemResource(path));}
 @GetMapping("/notifications") public ApiResponse<?> notifications(@AuthenticationPrincipal Jwt jwt){var a=access.actor(jwt);return ApiResponse.ok(db.queryForList("select * from notification where user_id=? order by id desc limit 200",a.id()));}
 @PostMapping("/notifications/{id}/read") public ApiResponse<?> read(@AuthenticationPrincipal Jwt jwt,@PathVariable long id){var a=access.actor(jwt);db.update("update notification set is_read=true where id=? and user_id=?",id,a.id());return ApiResponse.ok(null);}
 @GetMapping("/audit") public ApiResponse<?> audit(@AuthenticationPrincipal Jwt jwt){var a=access.actor(jwt);access.manager(a);return ApiResponse.ok(a.role().equals("ADMIN")?db.queryForList("select * from audit_log order by id desc limit 1000"):db.queryForList("select * from audit_log where actor_id=? or area_id in(select area_id from user_area where user_id=?) order by id desc limit 1000",a.id(),a.id()));}
 @GetMapping("/handbooks") public ApiResponse<?> books(@AuthenticationPrincipal Jwt jwt){access.actor(jwt);return ApiResponse.ok(db.queryForList("select * from handbook order by id desc"));}
 @PostMapping("/handbooks") public ApiResponse<?> book(@AuthenticationPrincipal Jwt jwt,@RequestBody Map<String,Object>b){var a=access.actor(jwt);access.manager(a);String title=text(b,"title",200),category=text(b,"category",100),steps=text(b,"steps",10000);db.update("insert into handbook(title,category,steps,review_points,reference_source) values(?,?,?,?,?)",title,category,steps,Objects.toString(b.get("reviewPoints"),""),Objects.toString(b.get("source"),""));access.audit(a,"CREATE","HANDBOOK",title,null,b);return ApiResponse.ok(null);}
 @PutMapping("/handbooks/{id}") public ApiResponse<?> updateBook(@AuthenticationPrincipal Jwt jwt,@PathVariable long id,@RequestBody Map<String,Object>b){var a=access.actor(jwt);access.manager(a);var before=access.one("select * from handbook where id=?",id);db.update("update handbook set title=?,category=?,steps=?,review_points=?,reference_source=?,updated_at=CURRENT_TIMESTAMP where id=?",text(b,"title",200),text(b,"category",100),text(b,"steps",10000),Objects.toString(b.get("reviewPoints"),""),Objects.toString(b.get("source"),""),id);access.audit(a,"UPDATE","HANDBOOK",id,before,b);return ApiResponse.ok(null);}
 @DeleteMapping("/handbooks/{id}") public ApiResponse<?> deleteBook(@AuthenticationPrincipal Jwt jwt,@PathVariable long id){var a=access.actor(jwt);access.manager(a);var before=access.one("select * from handbook where id=?",id);db.update("delete from handbook where id=?",id);access.audit(a,"DELETE","HANDBOOK",id,before,null);return ApiResponse.ok(null);}
}
